const D=1.1,GC=2,GR=2;const DIR={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};const S=Math.SQRT1_2;const Q={up:[-S,0,0,S],down:[S,0,0,S],left:[0,0,S,S],right:[0,0,-S,S]};
const won=s=>s.c===GC&&s.r===GR;const dist=s=>Math.abs(GC-s.c)+Math.abs(GR-s.r);
export function initialState(){return{c:0,r:0,moves:0,hint:false,msg:''};}
export function reduce({state,event}){if(event.type!=='action')return state;const s=state;if(won(s))return s;const a=event.action;if(a==='hint')return{...s,hint:true,msg:''};const d=DIR[a];if(!d)return s;const c=s.c+d[0],r=s.r+d[1];if(c<0||c>2||r<0||r>2)return{...s,msg:'That move would leave the board. Try another direction.'};return{c,r,moves:s.moves+1,hint:false,msg:''};}
export function evaluate({state}){const s=state||initialState();const w=won(s);const x=(s.c-1)*D,z=(1-s.r)*D;const hd=s.c<GC?'right':'up';const goal=w?{status:'won',message:'You reached the goal in '+s.moves+' moves. The shortest route is 4 moves.'+(s.moves===4?' Perfect route!':' Press Reset to try for 4.')}:{status:'playing',message:s.msg||(s.hint?'Hint: move '+hd[0].toUpperCase()+hd.slice(1)+' to get one step closer.':'Reach the gold goal square. '+dist(s)+' steps to go.')};return{nodes:{tokenN:{position:[x,w?0.36:0.3,z]},hintN:{visible:s.hint&&!w,position:[x,0.3,z],quaternion:Q[hd]}},readouts:{moves:s.moves,dist:dist(s)},goal};}
